    pivots = {}
    for row in rows:
        v = [Q(x).numerator*pow(Q(x).denominator,-1,p)%p
             for x in row]
        for j,w in sorted(pivots.items()):
            c = v[j]
            if c:
                v = [(a-c*b)%p for a,b in zip(v,w)]
        if any(v):
            j = next(j for j,x in enumerate(v) if x)
            c = pow(v[j],-1,p)
            pivots[j] = [x*c%p for x in v]
    return len(pivots)

# Coefficients of the weighted set-partition polynomial.
invodd = {
    s:pow(prod(range(1,2*s+2,2)),-1,p)
    for s in range(1,24)
}

@lru_cache(None)
def bell(t):
